SET search_path TO akis, public;

CREATE TABLE prosedur_adim_niyeti (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY, proje_id BIGINT NOT NULL REFERENCES proje(id), calistirma_id BIGINT NOT NULL,
 calistirma_adimi_id BIGINT NOT NULL, prosedur_adim_kaniti_id BIGINT NOT NULL, calistirma_nesil_no BIGINT NOT NULL,
 isleyici_referansi VARCHAR(200) NOT NULL, hedef_kaynagi_id BIGINT NOT NULL REFERENCES hedef_kaynagi(id), hedef_nesil_no BIGINT NOT NULL,
 hedef_fiziksel_ozeti CHAR(64) NOT NULL, hedef_kimlik_surumu INTEGER NOT NULL, yayin_ozeti CHAR(64) NOT NULL,
 plan_ozeti CHAR(64) NOT NULL, runtime_plan_ozeti CHAR(64) NOT NULL, komut_ozeti CHAR(64) NOT NULL, operasyon_anahtari_ozeti CHAR(64) NOT NULL,
 uuid UUID NOT NULL DEFAULT gen_random_uuid(), olusturulma_zamani TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 olusturan_kullanici_id BIGINT REFERENCES kullanici(id), guncellenme_zamani TIMESTAMPTZ,
 guncelleyen_kullanici_id BIGINT REFERENCES kullanici(id), versiyon_no BIGINT NOT NULL DEFAULT 1,
 CONSTRAINT pk_prosedur_adim_niyeti PRIMARY KEY(id),CONSTRAINT uq_prosedur_adim_niyeti_uuid UNIQUE(uuid),
 CONSTRAINT uq_prosedur_adim_niyeti_adim UNIQUE(calistirma_adimi_id),CONSTRAINT uq_prosedur_adim_niyeti_operasyon UNIQUE(hedef_kaynagi_id,operasyon_anahtari_ozeti),
 CONSTRAINT fk_prosedur_adim_niyeti_run FOREIGN KEY(proje_id,calistirma_id) REFERENCES calistirma(proje_id,id),
 CONSTRAINT fk_prosedur_adim_niyeti_adim FOREIGN KEY(proje_id,calistirma_adimi_id) REFERENCES calistirma_adimi(proje_id,id),
 CONSTRAINT fk_prosedur_adim_niyeti_kanit FOREIGN KEY(proje_id,prosedur_adim_kaniti_id) REFERENCES prosedur_adim_kaniti(proje_id,id),
 CONSTRAINT ck_prosedur_adim_niyeti_ozet CHECK(hedef_fiziksel_ozeti~'^[0-9a-f]{64}$' AND yayin_ozeti~'^[0-9a-f]{64}$' AND plan_ozeti~'^[0-9a-f]{64}$' AND runtime_plan_ozeti~'^[0-9a-f]{64}$' AND komut_ozeti~'^[0-9a-f]{64}$' AND operasyon_anahtari_ozeti~'^[0-9a-f]{64}$'),
 CONSTRAINT ck_prosedur_adim_niyeti_audit CHECK(versiyon_no=1 AND guncellenme_zamani IS NULL AND guncelleyen_kullanici_id IS NULL)
);
CREATE TRIGGER trg_prosedur_adim_niyeti_degismez BEFORE UPDATE OR DELETE ON prosedur_adim_niyeti FOR EACH ROW EXECUTE FUNCTION degismez_calistirma_kanitini_koru();

CREATE FUNCTION prosedur_calistirmayi_baslat(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_runtime_plan_ozeti TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_h hedef_kaynagi%ROWTYPE;v_y yayin%ROWTYPE;v_s senaryo%ROWTYPE;v_sayi INTEGER;
BEGIN
 SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;
 SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;
 SELECT * INTO v_h FROM hedef_kaynagi WHERE id=v_d.hedef_kaynagi_id AND uuid=p_hedef_kaynagi_uuid FOR UPDATE;
 SELECT y.* INTO v_y FROM is_talebi i JOIN yayin y ON y.id=i.yayin_id AND y.proje_id=i.proje_id WHERE i.id=v_c.is_talebi_id;
 SELECT * INTO v_s FROM senaryo WHERE id=v_y.senaryo_id;
 IF v_y.durum<>'AKTIF' OR v_y.fiziksel_manifesto->>'runtimeCapability'<>'ORACLE_PROCEDURE_V1' OR v_y.fiziksel_manifesto->>'runtimePlanHash'<>p_runtime_plan_ozeti
 OR v_c.yayin_ozeti<>v_y.fiziksel_manifesto->>'releaseHash' OR v_c.plan_ozeti<>v_s.plan_ozeti OR v_d.durum NOT IN('SAHIPLENILDI','CALISIYOR')
 OR v_d.nesil_no<>p_calistirma_nesil_no OR v_d.isleyici_referansi<>p_isleyici_referansi OR v_d.kiralama_bitis_zamani<=clock_timestamp()
 OR v_h.durum<>'SAHIPLENILDI' OR v_h.nesil_no<>p_hedef_nesil_no OR v_h.kiralama_bitis_zamani<=clock_timestamp() THEN RETURN FALSE;END IF;
 SELECT jsonb_array_length(v_s.plan#>'{executable,definition,tasks}') INTO v_sayi;IF v_sayi NOT BETWEEN 1 AND 1000 OR jsonb_array_length(v_y.fiziksel_manifesto->'bindings')<>v_sayi THEN RETURN FALSE;END IF;
 INSERT INTO calistirma_adimi(proje_id,calistirma_id,adim_kodu,tur,sira_no,ad)
 SELECT v_c.proje_id,v_c.id,t->>'id','PROSEDUR',n,coalesce(nullif(t->>'name',''),t->>'id') FROM jsonb_array_elements(v_s.plan#>'{executable,definition,tasks}') WITH ORDINALITY x(t,n)
 ON CONFLICT(calistirma_id,adim_kodu) DO NOTHING;
 INSERT INTO prosedur_adim_kaniti(proje_id,calistirma_id,calistirma_adimi_id,sira_no,runtime_plan_ozeti,komut_ozeti,baglanti_rolu,risk,hata_politikasi,tanim_veri_nesnesi_uuid,baglanti_surumu_uuid,sema_goruntusu_uuid,sema_parmak_izi)
 SELECT v_c.proje_id,v_c.id,ca.id,n,p_runtime_plan_ozeti,encode(sha256(convert_to(t->>'command','UTF8')),'hex'),t->>'connectionRole',t->>'riskClass',coalesce(t->>'onError','STOP'),(b->>'definitionDataObjectUuid')::uuid,(b->>'connectionVersionUuid')::uuid,(b->>'schemaSnapshotUuid')::uuid,b->>'schemaSnapshotFingerprint'
 FROM jsonb_array_elements(v_s.plan#>'{executable,definition,tasks}') WITH ORDINALITY x(t,n) JOIN calistirma_adimi ca ON ca.calistirma_id=v_c.id AND ca.adim_kodu=t->>'id' JOIN jsonb_array_elements(v_y.fiziksel_manifesto->'bindings') b ON b->>'nodeCode'=t->>'id'
 ON CONFLICT(calistirma_adimi_id) DO NOTHING;
 INSERT INTO prosedur_adim_durumu(proje_id,calistirma_id,calistirma_adimi_id,prosedur_adim_kaniti_id) SELECT proje_id,calistirma_id,calistirma_adimi_id,id FROM prosedur_adim_kaniti WHERE calistirma_id=v_c.id ON CONFLICT(calistirma_adimi_id) DO NOTHING;
 IF (SELECT count(*) FROM prosedur_adim_kaniti WHERE calistirma_id=v_c.id)<>v_sayi THEN RETURN FALSE;END IF;
 IF v_d.durum='CALISIYOR' THEN RETURN EXISTS(SELECT 1 FROM calistirma_olayi WHERE calistirma_id=v_c.id AND tur='PROCEDURE_PREPARED' AND veri->>'runtimePlanHash'=p_runtime_plan_ozeti);END IF;
 UPDATE calistirma_durumu SET durum='CALISIYOR',baslama_zamani=coalesce(baslama_zamani,clock_timestamp()),son_olay_no=son_olay_no+1,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_d.id RETURNING * INTO v_d;
 INSERT INTO calistirma_olayi(proje_id,calistirma_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_d.son_olay_no,'PROCEDURE_PREPARED',clock_timestamp(),jsonb_build_object('generation',p_calistirma_nesil_no,'workerReference',p_isleyici_referansi,'targetResourceUuid',p_hedef_kaynagi_uuid,'targetGeneration',p_hedef_nesil_no,'runtimePlanHash',p_runtime_plan_ozeti,'taskCount',v_sayi));RETURN TRUE;
END $$;

CREATE FUNCTION prosedur_adimini_baslat(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_adim_kodu TEXT,p_operasyon_anahtari_ozeti TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_h hedef_kaynagi%ROWTYPE;v_a calistirma_adimi%ROWTYPE;v_k prosedur_adim_kaniti%ROWTYPE;v_sd prosedur_adim_durumu%ROWTYPE;
BEGIN SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;SELECT * INTO v_h FROM hedef_kaynagi WHERE id=v_d.hedef_kaynagi_id AND uuid=p_hedef_kaynagi_uuid FOR UPDATE;SELECT * INTO v_a FROM calistirma_adimi WHERE calistirma_id=v_c.id AND adim_kodu=p_adim_kodu;SELECT * INTO v_k FROM prosedur_adim_kaniti WHERE calistirma_adimi_id=v_a.id;SELECT * INTO v_sd FROM prosedur_adim_durumu WHERE calistirma_adimi_id=v_a.id FOR UPDATE;
 IF v_sd.durum='CALISIYOR' THEN RETURN TRUE;END IF;IF v_d.durum<>'CALISIYOR' OR v_d.nesil_no<>p_calistirma_nesil_no OR v_d.isleyici_referansi<>p_isleyici_referansi OR v_d.kiralama_bitis_zamani<=clock_timestamp() OR v_h.nesil_no<>p_hedef_nesil_no OR v_h.durum<>'SAHIPLENILDI' OR v_sd.durum<>'BEKLIYOR' OR EXISTS(SELECT 1 FROM prosedur_adim_durumu s JOIN prosedur_adim_kaniti k ON k.id=s.prosedur_adim_kaniti_id WHERE s.calistirma_id=v_c.id AND k.sira_no<v_k.sira_no AND s.durum NOT IN('BASARILI','HATA_DEVAM')) THEN RETURN FALSE;END IF;
 IF v_k.risk<>'READ_ONLY' THEN IF p_operasyon_anahtari_ozeti !~ '^[0-9a-f]{64}$' THEN RETURN FALSE;END IF;INSERT INTO prosedur_adim_niyeti(proje_id,calistirma_id,calistirma_adimi_id,prosedur_adim_kaniti_id,calistirma_nesil_no,isleyici_referansi,hedef_kaynagi_id,hedef_nesil_no,hedef_fiziksel_ozeti,hedef_kimlik_surumu,yayin_ozeti,plan_ozeti,runtime_plan_ozeti,komut_ozeti,operasyon_anahtari_ozeti) VALUES(v_c.proje_id,v_c.id,v_a.id,v_k.id,p_calistirma_nesil_no,p_isleyici_referansi,v_h.id,p_hedef_nesil_no,v_h.fiziksel_ozet,v_h.kimlik_surumu,v_c.yayin_ozeti,v_c.plan_ozeti,v_k.runtime_plan_ozeti,v_k.komut_ozeti,p_operasyon_anahtari_ozeti);ELSIF p_operasyon_anahtari_ozeti IS NOT NULL THEN RETURN FALSE;END IF;
 UPDATE calistirma_durumu SET son_olay_no=son_olay_no+1 WHERE id=v_d.id RETURNING * INTO v_d;UPDATE prosedur_adim_durumu SET durum='CALISIYOR',son_olay_no=v_d.son_olay_no,baslama_zamani=clock_timestamp(),guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_sd.id;
 INSERT INTO calistirma_olayi(proje_id,calistirma_id,calistirma_adimi_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_a.id,v_d.son_olay_no,'PROCEDURE_TASK_STARTED',clock_timestamp(),jsonb_build_object('stepCode',p_adim_kodu,'operationKeyHash',p_operasyon_anahtari_ozeti));RETURN TRUE;END $$;

CREATE FUNCTION prosedur_adimini_basarili_tamamla(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_adim_kodu TEXT,p_satir_sayisi BIGINT,p_bayt_sayisi BIGINT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_a calistirma_adimi%ROWTYPE;v_sd prosedur_adim_durumu%ROWTYPE;
BEGIN SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;SELECT * INTO v_a FROM calistirma_adimi WHERE calistirma_id=v_c.id AND adim_kodu=p_adim_kodu;SELECT * INTO v_sd FROM prosedur_adim_durumu WHERE calistirma_adimi_id=v_a.id FOR UPDATE;IF v_sd.durum='BASARILI' THEN RETURN v_sd.satir_sayisi=p_satir_sayisi AND v_sd.bayt_sayisi=p_bayt_sayisi;END IF;IF v_d.durum<>'CALISIYOR' OR v_d.nesil_no<>p_calistirma_nesil_no OR v_d.isleyici_referansi<>p_isleyici_referansi OR v_sd.durum<>'CALISIYOR' THEN RETURN FALSE;END IF;UPDATE calistirma_durumu SET son_olay_no=son_olay_no+1 WHERE id=v_d.id RETURNING * INTO v_d;UPDATE prosedur_adim_durumu SET durum='BASARILI',son_olay_no=v_d.son_olay_no,bitis_zamani=clock_timestamp(),satir_sayisi=p_satir_sayisi,bayt_sayisi=p_bayt_sayisi,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_sd.id;INSERT INTO calistirma_olayi(proje_id,calistirma_id,calistirma_adimi_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_a.id,v_d.son_olay_no,'PROCEDURE_TASK_SUCCEEDED',clock_timestamp(),jsonb_build_object('stepCode',p_adim_kodu,'rowCount',p_satir_sayisi,'byteCount',p_bayt_sayisi));RETURN TRUE;END $$;

CREATE FUNCTION prosedur_adimini_basarisiz_tamamla(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_adim_kodu TEXT,p_hata_kodu TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_a calistirma_adimi%ROWTYPE;v_k prosedur_adim_kaniti%ROWTYPE;v_sd prosedur_adim_durumu%ROWTYPE;v_son VARCHAR(30);
BEGIN SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;SELECT * INTO v_a FROM calistirma_adimi WHERE calistirma_id=v_c.id AND adim_kodu=p_adim_kodu;SELECT * INTO v_k FROM prosedur_adim_kaniti WHERE calistirma_adimi_id=v_a.id;SELECT * INTO v_sd FROM prosedur_adim_durumu WHERE calistirma_adimi_id=v_a.id FOR UPDATE;v_son=CASE WHEN v_k.hata_politikasi='CONTINUE' THEN 'HATA_DEVAM' ELSE 'BASARISIZ' END;IF v_sd.durum=v_son THEN RETURN v_sd.hata_kodu=p_hata_kodu;END IF;IF v_d.durum<>'CALISIYOR' OR v_sd.durum<>'CALISIYOR' THEN RETURN FALSE;END IF;UPDATE calistirma_durumu SET son_olay_no=son_olay_no+1 WHERE id=v_d.id RETURNING * INTO v_d;UPDATE prosedur_adim_durumu SET durum=v_son,son_olay_no=v_d.son_olay_no,bitis_zamani=clock_timestamp(),hata_kodu=p_hata_kodu,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_sd.id;INSERT INTO calistirma_olayi(proje_id,calistirma_id,calistirma_adimi_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_a.id,v_d.son_olay_no,'PROCEDURE_TASK_FAILED',clock_timestamp(),jsonb_build_object('stepCode',p_adim_kodu,'errorCode',p_hata_kodu,'continued',v_son='HATA_DEVAM'));RETURN TRUE;END $$;

CREATE FUNCTION prosedur_adimini_sonuc_belirsiz_isaretle(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_adim_kodu TEXT,p_hata_kodu TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_a calistirma_adimi%ROWTYPE;v_k prosedur_adim_kaniti%ROWTYPE;v_sd prosedur_adim_durumu%ROWTYPE;v_h hedef_kaynagi%ROWTYPE;
BEGIN SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;SELECT * INTO v_h FROM hedef_kaynagi WHERE id=v_d.hedef_kaynagi_id AND uuid=p_hedef_kaynagi_uuid FOR UPDATE;SELECT * INTO v_a FROM calistirma_adimi WHERE calistirma_id=v_c.id AND adim_kodu=p_adim_kodu;SELECT * INTO v_k FROM prosedur_adim_kaniti WHERE calistirma_adimi_id=v_a.id;SELECT * INTO v_sd FROM prosedur_adim_durumu WHERE calistirma_adimi_id=v_a.id FOR UPDATE;IF v_sd.durum='SONUC_BELIRSIZ' THEN RETURN TRUE;END IF;IF v_sd.durum<>'CALISIYOR' OR v_k.risk='READ_ONLY' OR NOT EXISTS(SELECT 1 FROM prosedur_adim_niyeti WHERE calistirma_adimi_id=v_a.id) THEN RETURN FALSE;END IF;UPDATE prosedur_adim_durumu SET durum='SONUC_BELIRSIZ',bitis_zamani=clock_timestamp(),hata_kodu=p_hata_kodu,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_sd.id;UPDATE hedef_kaynagi SET durum='ASKIDA',calistirma_id=NULL,kiralama_bitis_zamani=NULL,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_h.id;UPDATE calistirma_durumu SET durum='SONUC_BELIRSIZ',kiralama_bitis_zamani=NULL,bitis_zamani=clock_timestamp(),son_olay_no=son_olay_no+1,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_d.id RETURNING * INTO v_d;INSERT INTO calistirma_olayi(proje_id,calistirma_id,calistirma_adimi_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_a.id,v_d.son_olay_no,'PROCEDURE_TASK_OUTCOME_UNKNOWN',clock_timestamp(),jsonb_build_object('stepCode',p_adim_kodu,'errorCode',p_hata_kodu,'requiresReconciliation',true));RETURN TRUE;END $$;

CREATE FUNCTION prosedur_calistirmayi_basarili_tamamla(p_calistirma_uuid UUID,p_isleyici_referansi TEXT,p_calistirma_nesil_no BIGINT,p_hedef_kaynagi_uuid UUID,p_hedef_nesil_no BIGINT,p_runtime_plan_ozeti TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path=akis,public AS $$
DECLARE v_c calistirma%ROWTYPE;v_d calistirma_durumu%ROWTYPE;v_h hedef_kaynagi%ROWTYPE;
BEGIN SELECT * INTO v_c FROM calistirma WHERE uuid=p_calistirma_uuid;IF NOT FOUND THEN RETURN FALSE;END IF;SELECT * INTO v_d FROM calistirma_durumu WHERE calistirma_id=v_c.id FOR UPDATE;IF v_d.durum='BASARILI' THEN RETURN TRUE;END IF;SELECT * INTO v_h FROM hedef_kaynagi WHERE id=v_d.hedef_kaynagi_id AND uuid=p_hedef_kaynagi_uuid FOR UPDATE;IF v_d.durum<>'CALISIYOR' OR v_d.nesil_no<>p_calistirma_nesil_no OR v_d.isleyici_referansi<>p_isleyici_referansi OR v_h.nesil_no<>p_hedef_nesil_no OR EXISTS(SELECT 1 FROM prosedur_adim_durumu WHERE calistirma_id=v_c.id AND durum NOT IN('BASARILI','HATA_DEVAM')) OR NOT EXISTS(SELECT 1 FROM prosedur_adim_kaniti WHERE calistirma_id=v_c.id AND runtime_plan_ozeti=p_runtime_plan_ozeti) THEN RETURN FALSE;END IF;UPDATE hedef_kaynagi SET durum='BOS',calistirma_id=NULL,kiralama_bitis_zamani=NULL,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_h.id;UPDATE calistirma_durumu SET durum='BASARILI',kiralama_bitis_zamani=NULL,bitis_zamani=clock_timestamp(),son_olay_no=son_olay_no+1,guncellenme_zamani=clock_timestamp(),versiyon_no=versiyon_no+1 WHERE id=v_d.id RETURNING * INTO v_d;INSERT INTO calistirma_olayi(proje_id,calistirma_id,olay_no,tur,olay_zamani,veri) VALUES(v_c.proje_id,v_c.id,v_d.son_olay_no,'PROCEDURE_SUCCEEDED',clock_timestamp(),jsonb_build_object('runtimePlanHash',p_runtime_plan_ozeti,'targetGeneration',p_hedef_nesil_no));RETURN TRUE;END $$;

REVOKE ALL ON FUNCTION prosedur_calistirmayi_baslat(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION prosedur_adimini_baslat(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION prosedur_adimini_basarili_tamamla(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT,BIGINT,BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION prosedur_adimini_basarisiz_tamamla(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION prosedur_adimini_sonuc_belirsiz_isaretle(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION prosedur_calistirmayi_basarili_tamamla(UUID,TEXT,BIGINT,UUID,BIGINT,TEXT) FROM PUBLIC;
